import pytest
from click.testing import CliRunner
import click

def test_deprecated_option_warns():
    runner = CliRunner()

    @click.command()
    @click.option("--old-name", help="This is deprecated.")
    @click.option("--new-name", help="Use this instead.")
    def cli(old_name, new_name):
        click.echo(f"old_name={old_name}, new_name={new_name}")

    # This test should fail because there's no mechanism to mark --old-name as deprecated
    # and issue a warning when it's used.
    result = runner.invoke(cli, ["--old-name", "value"])
    assert "Option '--old-name' is deprecated. Use '--new-name' instead." in result.output
    assert result.exit_code == 0

def test_deprecated_option_with_renamed_message():
    runner = CliRunner()

    @click.command()
    @click.option("--count", help="Deprecated, use --greetings-count instead.")
    @click.option("--greetings-count", help="Number of greetings.")
    def hello(count, greetings_count):
        click.echo(f"count={count}, greetings_count={greetings_count}")

    # This test should fail because there's no mechanism to mark --count as deprecated
    # and issue a warning when it's used, especially with a custom message.
    result = runner.invoke(hello, ["--count", "5"])
    assert "Option '--count' is deprecated. Use '--greetings-count' instead." in result.output
    assert result.exit_code == 0

def test_deprecated_option_disallows_both():
    runner = CliRunner()

    @click.command()
    @click.option("--count", help="Deprecated, use --greetings-count instead.")
    @click.option("--greetings-count", help="Number of greetings.")
    def hello(count, greetings_count):
        click.echo(f"count={count}, greetings_count={greetings_count}")

    # This test should fail because there's no mechanism to prevent using both
    # the deprecated and the new option simultaneously.
    result = runner.invoke(hello, ["--count", "5", "--greetings-count", "10"])
    assert "Cannot use both '--count' and '--greetings-count'." in result.output
    assert result.exit_code != 0
